from flask import Flask, request, jsonify, g
import threading
import uuid
from collections import defaultdict
from datetime import datetime, timezone
from typing import Dict, Optional, Any, List
import re

app = Flask(__name__)

# ============== DATA STRUCTURES ==============
class Team:
    def __init__(self, name: str, capacity: int):
        self.id = str(uuid.uuid4())
        self.name = name
        self.capacity = capacity
        self.created_at = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        self.todos: Dict[int, dict] = {}  # todo_id -> todo object
        self.next_todo_id = 1  # Per-team sequence starting from 1
        self.lock = threading.Lock()
        self.completed_count = 0  # Track completed todos dynamically
        self.rate_limit_requests: List[float] = []  # Track request timestamps

teams: Dict[str, Team] = {}
teams_lock = threading.Lock()

# Rate limiting storage: team_id -> list of request timestamps
rate_limits: Dict[str, List[float]] = defaultdict(list)
rate_limit_lock = threading.Lock()
RATE_LIMIT_PER_MINUTE = 100

# Global lock for rate limit checking
global_lock = threading.Lock()

def get_current_timestamp() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

def validate_sql_injection(title: str) -> bool:
    """Check for SQL injection patterns in title. Returns True if injection detected (invalid)."""
    if not title or len(title) == 0:
        return False

    # Case-insensitive check
    title_lower = title.lower()

    # Patterns to detect - SQL keywords in suspicious contexts
    # Keywords that indicate injection attempts
    sql_keywords = ["select", "insert", "update", "delete", "drop", "union", "alter", "create", "truncate"]

    for keyword in sql_keywords:
        # Look for keyword followed by suspicious patterns
        # Pattern: keyword at start, or after space, followed by SQL syntax
        # But NOT if it's part of a legitimate word like "SELECT" in "RESELECT"

        # Check for common SQL injection patterns
        patterns = [
            r"'\s*--",           # quote followed by space and comment
            r"'\s*or\s+['\"]?1['\"]?\s*=\s*['\"]?1",  # OR 1=1
            r"'\s*or\s+",         # OR with quote
            r"--\s*$",            # comment at end
            r";\s*--",            # semicolon then comment
            r";\s*drop",          # drop after semicolon
            r";\s*delete",        # delete after semicolon
            r";\s*update",        # update after semicolon
            r";\s*insert",        # insert after semicolon
            r";\s*select",        # select after semicolon
            r"'\s*union",         # union with quote
            r"union\s+select",    # union select pattern
        ]

        for pattern in patterns:
            if re.search(pattern, title_lower):
                return True

        # Also check if keyword appears with suspicious positioning
        # e.g., "'; DROP" - quote, semicolon, keyword
        if f"'{keyword}" in title_lower or f"' {keyword}" in title_lower:
            # But allow legitimate uses - check context
            # If it's just the word in normal text, it's OK
            # We need to be careful: "SELECT best practices" should pass
            # But "'; DROP TABLE" should fail
            pass

    # More aggressive check: look for specific injection patterns
    # Single quotes followed by SQL keywords or operators
    dangerous = [
        r"'\s*(or|and|;|--)",  # quote then OR/AND/semicolon/comment
        r"--",                  # SQL comment
        r";\s*(drop|delete|update|insert|select|union)",  # statement terminator
        r"^--",                 # starts with comment
    ]

    for pat in dangerous:
        if re.search(pat, title_lower):
            return True

    return False

def check_rate_limit(team_id: str) -> bool:
    """Check if team has exceeded rate limit. Returns True if allowed."""
    with rate_limit_lock:
        current_time = datetime.now(timezone.utc).timestamp()
        # Clean old requests (older than 60 seconds)
        rate_limits[team_id] = [t for t in rate_limits[team_id] if current_time - t < 60]

        if len(rate_limits[team_id]) >= RATE_LIMIT_PER_MINUTE:
            return False

        rate_limits[team_id].append(current_time)
        return True

def get_rate_limit_retry_after(team_id: str) -> int:
    """Get seconds until rate limit resets."""
    with rate_limit_lock:
        current_time = datetime.now(timezone.utc).timestamp()
        oldest = min(rate_limits[team_id]) if rate_limits[team_id] else current_time
        return max(0, int(oldest + 60 - current_time))

# ============== MIDDLEWARE ==============
@app.before_request
def before_request():
    # Check rate limit for all endpoints except POST /teams
    if request.endpoint != 'create_team':
        team_id = request.headers.get('X-Team-ID')
        if not team_id:
            g.team_id = None
            return jsonify({
                "error": "Unauthorized",
                "message": "Missing or invalid X-Team-ID header"
            }), 401

        # Check if team exists
        with teams_lock:
            if team_id not in teams:
                g.team_id = None
                return jsonify({
                    "error": "Unauthorized",
                    "message": "Missing or invalid X-Team-ID header"
                }), 401

        g.team_id = team_id

        # Check rate limit
        if not check_rate_limit(team_id):
            return jsonify({
                "error": "Rate limit exceeded",
                "retry_after": get_rate_limit_retry_after(team_id)
            }), 429

    g.team_id = None  # For POST /teams

# ============== TEAM ENDPOINTS ==============
@app.route('/teams', methods=['POST'])
def create_team():
    # Get JSON data
    try:
        data = request.get_json(force=True)
    except Exception:
        return jsonify({"error": "Bad request"}), 400

    if not data or not isinstance(data, dict):
        return jsonify({"error": "Bad request"}), 400

    # Validate name
    name = data.get('name')
    if name is None:
        return jsonify({"error": "Bad request"}), 400

    if not isinstance(name, str):
        return jsonify({"error": "Bad request"}), 400

    name = name.strip()
    if not name:
        return jsonify({"error": "Bad request"}), 400

    # Validate capacity
    capacity = data.get('capacity')
    if capacity is None:
        return jsonify({"error": "Bad request"}), 400

    if not isinstance(capacity, int) or isinstance(capacity, bool):
        return jsonify({"error": "Bad request"}), 400

    if capacity <= 0:
        return jsonify({"error": "Bad request"}), 400

    # Create team
    team = Team(name=name, capacity=capacity)

    with teams_lock:
        teams[team.id] = team

    return jsonify({
        "team_id": team.id,
        "name": team.name,
        "capacity": team.capacity,
        "created_at": team.created_at
    }), 201

@app.route('/teams/<team_id>/stats', methods=['GET'])
def get_team_stats(team_id):
    # Authorization: team_id in URL must match X-Team-ID header
    header_team_id = request.headers.get('X-Team-ID')

    if not header_team_id:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    with teams_lock:
        team = teams.get(header_team_id)
        if not team:
            return jsonify({
                "error": "Unauthorized",
                "message": "Missing or invalid X-Team-ID header"
            }), 401

        # Check if URL team_id matches header team_id (cross-team prevention)
        if team.id != team_id:
            return jsonify({"error": "Forbidden"}), 403

        # Count todos for this team
        total_todos = len(team.todos)
        completed = sum(1 for t in team.todos.values() if t.get('completed', False))

        # Calculate capacity used percentage
        if team.capacity > 0:
            capacity_used = f"{(total_todos / team.capacity) * 100:.1f}%"
        else:
            capacity_used = "0.0%"

    return jsonify({
        "total_todos": total_todos,
        "completed": completed,
        "capacity_used": capacity_used
    }), 200

# ============== TODO ENDPOINTS ==============
@app.route('/todos', methods=['GET'])
def get_todos():
    team_id = g.team_id
    if not team_id:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    with teams_lock:
        team = teams.get(team_id)
        if not team:
            return jsonify({
                "error": "Unauthorized",
                "message": "Missing or invalid X-Team-ID header"
            }), 401

        todos_list = list(team.todos.values())

    # Parse query parameters
    page = request.args.get('page', type=int)
    sort = request.args.get('sort', 'created_asc')
    completed_filter = request.args.get('completed')
    tag_filter = request.args.get('tag')

    # Validate page
    if page is None or page < 1:
        return jsonify({"error": "Bad request"}), 400

    # Validate sort
    if sort not in ['created_asc', 'created_desc', 'title']:
        return jsonify({"error": "Bad request"}), 400

    # Filter and sort
    filtered = todos_list

    # Apply completion filter
    if completed_filter is not None:
        if completed_filter == 'true':
            filtered = [t for t in filtered if t.get('completed', False)]
        elif completed_filter == 'false':
            filtered = [t for t in filtered if not t.get('completed', False)]

    # Apply tag filter
    if tag_filter is not None:
        filtered = [t for t in filtered if tag_filter in t.get('tags', [])]

    # Sort
    if sort == 'created_asc':
        filtered.sort(key=lambda x: x.get('created_at', ''))
    elif sort == 'created_desc':
        filtered.sort(key=lambda x: x.get('created_at', ''), reverse=True)
    elif sort == 'title':
        filtered.sort(key=lambda x: x.get('title', ''))

    # Pagination
    page_size = min(50, len(filtered))  # Max 50 items per page
    start_idx = (page - 1) * 50
    end_idx = start_idx + page_size
    paginated = filtered[start_idx:end_idx]

    total = len(filtered)
    next_cursor = None
    if end_idx < total:
        next_cursor = page + 1

    return jsonify({
        "todos": paginated,
        "page": page,
        "page_size": page_size,
        "next_cursor": next_cursor,
        "total": total
    }), 200

@app.route('/todos', methods=['POST'])
def create_todo():
    team_id = g.team_id
    if not team_id:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    # Get JSON
    try:
        data = request.get_json(force=True)
    except Exception:
        return jsonify({"error": "Bad request"}), 400

    if not isinstance(data, dict):
        return jsonify({"error": "Bad request"}), 400

    # Validate title
    title = data.get('title')
    if title is None:
        return jsonify({"error": "Bad request"}), 400

    if not isinstance(title, str):
        return jsonify({"error": "Bad request"}), 400

    title = title.strip()
    if not title:
        return jsonify({"error": "Bad request"}), 400

    # Check SQL injection
    if validate_sql_injection(title):
        return jsonify({"error": "Bad request"}), 400

    # Title length check
    if len(title) > 1000:
        return jsonify({"error": "Bad request"}), 400

    # Validate optional fields
    completed = data.get('completed', False)
    if not isinstance(completed, bool):
        completed = False

    tags = data.get('tags', [])
    if not isinstance(tags, list):
        tags = []
    for tag in tags:
        if not isinstance(tag, str):
            return jsonify({"error": "Bad request"}), 400
        if len(tag) > 100:
            return jsonify({"error": "Bad request"}), 400

    metadata = data.get('metadata', {})
    if not isinstance(metadata, dict):
        return jsonify({"error": "Bad request"}), 400

    # Check capacity
    with teams_lock:
        team = teams.get(team_id)
        if not team:
            return jsonify({
                "error": "Unauthorized",
                "message": "Team not found"
            }), 401

        # Check if at capacity
        if len(team.todos) >= team.capacity:
            return jsonify({
                "error": "Team capacity exceeded",
                "capacity": team.capacity,
                "current": len(team.todos)
            }), 403

        # Create todo
        todo_id = team.next_todo_id
        team.next_todo_id += 1

        todo = {
            "id": todo_id,
            "title": title,
            "team_id": team.id,
            "completed": completed,
            "version": 1,
            "created_at": get_current_timestamp(),
            "updated_at": get_current_timestamp(),
            "tags": tags,
            "metadata": metadata
        }

        team.todos[todo_id] = todo
        if completed:
            team.completed_count += 1

    return jsonify(todo), 201

@app.route('/todos/<int:todo_id>', methods=['GET'])
def get_todo(todo_id):
    team_id = g.team_id
    if not team_id:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    with teams_lock:
        team = teams.get(team_id)
        if not team:
            return jsonify({
                "error": "Unauthorized",
                "message": "Team not found"
            }), 401

        if todo_id not in team.todos:
            return jsonify({"error": "Todo not found"}), 404

        # Check if todo belongs to this team (isolation)
        if team.todos[todo_id].get('team_id') != team.id:
            return jsonify({"error": "Todo not found"}), 404

    todo = team.todos[todo_id].copy()
    return jsonify(todo), 200

@app.route('/todos/<int:todo_id>', methods=['PUT'])
def update_todo(todo_id):
    team_id = g.team_id
    if not team_id:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    # Check X-If-Version header
    if_version = request.headers.get('X-If-Version')
    if if_version is None:
        return jsonify({"error": "Bad request"}), 400

    # Validate version is numeric
    try:
        current_version = int(if_version)
    except ValueError:
        return jsonify({"error": "Bad request"}), 400

    with teams_lock:
        team = teams.get(team_id)
        if not team:
            return jsonify({
                "error": "Unauthorized",
                "message": "Team not found"
            }), 401

        if todo_id not in team.todos:
            return jsonify({"error": "Todo not found"}), 404

        todo = team.todos[todo_id]

        # Check ownership
        if todo.get('team_id') != team.id:
            return jsonify({"error": "Todo not found"}), 404

        # Check version
        if todo.get('version') != current_version:
            return jsonify({
                "error": "Version mismatch",
                "current_version": todo['version'],
                "provided_version": current_version
            }), 409

        # Get update data
        try:
            data = request.get_json(force=True)
        except:
            return jsonify({"error": "Bad request"}), 400

        if not isinstance(data, dict):
            return jsonify({"error": "Bad request"}), 400

        # Only update provided fields
        if 'title' in data:
            title = data['title']
            if not isinstance(title, str):
                return jsonify({"error": "Bad request"}), 400
            title = title.strip()
            if not title:
                return jsonify({"error": "Bad request"}), 400
            if len(title) > 1000:
                return jsonify({"error": "Bad request"}), 400
            if validate_sql_injection(title):
                return jsonify({"error": "Bad request"}), 400
            todo['title'] = title

        if 'completed' in data:
            if not isinstance(data['completed'], bool):
                return jsonify({"error": "Bad request"}), 400
            todo['completed'] = data['completed']
            # Update completed count
            if todo['completed']:
                team.completed_count += 1
            else:
                team.completed_count -= 1

        if 'tags' in data:
            tags = data['tags']
            if not isinstance(tags, list):
                return jsonify({"error": "Bad request"}), 400
            for tag in tags:
                if not isinstance(tag, str):
                    return jsonify({"error": "Bad request"}), 400
                if len(tag) > 100:
                    return jsonify({"error": "Bad request"}), 400
            todo['tags'] = tags

        if 'metadata' in data:
            metadata = data['metadata']
            if not isinstance(metadata, dict):
                return jsonify({"error": "Bad request"}), 400
            todo['metadata'] = metadata

        # Update version and timestamp
        todo['version'] += 1
        todo['updated_at'] = get_current_timestamp()

    return jsonify(todo), 200

@app.route('/todos/<int:todo_id>', methods=['DELETE'])
def delete_todo(todo_id):
    team_id = g.team_id
    if not team_id:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    with teams_lock:
        team = teams.get(team_id)
        if not team:
            return jsonify({
                "error": "Unauthorized",
                "message": "Team not found"
            }), 401

        if todo_id not in team.todos:
            return jsonify({"error": "Todo not found"}), 404

        # Check ownership
        if team.todos[todo_id].get('team_id') != team.id:
            return jsonify({"error": "Todo not found"}), 404

        # Delete
        del team.todos[todo_id]
        return jsonify({"id": todo_id, "deleted": True}), 200

@app.route('/todos/<int:todo_id>', methods=['PATCH'])
def patch_todo(todo_id):
    return jsonify({"error": "Method not allowed"}), 405

# ============== BATCH ENDPOINTS ==============
@app.route('/todos/batch', methods=['POST'])
def batch_update_todos():
    team_id = g.team_id
    if not team_id:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    # Get JSON
    try:
        data = request.get_json(force=True)
    except Exception:
        return jsonify({"error": "Bad request"}), 400

    if not isinstance(data, dict):
        return jsonify({"error": "Bad request"}), 400

    # Check updates field exists
    if 'updates' not in data:
        return jsonify({"error": "Bad request"}), 400

    updates = data['updates']
    if not isinstance(updates, list):
        return jsonify({"error": "Bad request"}), 400

    # Check size limit
    if len(updates) > 100:
        return jsonify({"error": "Bad request"}), 400

    # If empty, return success
    if len(updates) == 0:
        return jsonify({"updated": [], "count": 0}), 200

    # Get team
    with teams_lock:
        team = teams.get(team_id)
        if not team:
            return jsonify({
                "error": "Unauthorized",
                "message": "Team not found"
            }), 401

        # Validate each update item
        for update in updates:
            if not isinstance(update, dict):
                return jsonify({"error": "Bad request"}), 400

            if 'id' not in update:
                return jsonify({"error": "Bad request"}), 400

            todo_id = update['id']
            if not isinstance(todo_id, int):
                return jsonify({"error": "Bad request"}), 400

            # Check if todo exists and belongs to team
            if todo_id not in team.todos:
                return jsonify({"error": "Todo not found"}), 404

            if team.todos[todo_id].get('team_id') != team.id:
                return jsonify({"error": "Todo not found"}), 404

        # All validations passed, now apply updates atomically
        updated_todos = []
        for update in updates:
            todo_id = update['id']
            todo = team.todos[todo_id]

            # Increment version
            todo['version'] += 1
            todo['updated_at'] = get_current_timestamp()

            # Apply changes
            if 'title' in update:
                title = update['title']
                if not isinstance(title, str):
                    return jsonify({"error": "Bad request"}), 400
                title = title.strip()
                if not title:
                    return jsonify({"error": "Bad request"}), 400
                if len(title) > 1000:
                    return jsonify({"error": "Bad request"}), 400
                if validate_sql_injection(title):
                    return jsonify({"error": "Bad request"}), 400
                todo['title'] = title

            if 'completed' in update:
                if not isinstance(update['completed'], bool):
                    return jsonify({"error": "Bad request"}), 400
                todo['completed'] = update['completed']

            if 'tags' in update:
                tags = update['tags']
                if not isinstance(tags, list):
                    return jsonify({"error": "Bad request"}), 400
                for tag in tags:
                    if not isinstance(tag, str):
                        return jsonify({"error": "Bad request"}), 400
                    if len(tag) > 100:
                        return jsonify({"error": "Bad request"}), 400
                todo['tags'] = tags

            if 'metadata' in update:
                metadata = update['metadata']
                if not isinstance(metadata, dict):
                    return jsonify({"error": "Bad request"}), 400
                todo['metadata'] = metadata

            updated_todos.append(todo.copy())

        return jsonify({
            "updated": updated_todos,
            "count": len(updated_todos)
        }), 200

# ============== EXPORT ENDPOINT ==============
@app.route('/todos/export', methods=['GET'])
def export_todos():
    team_id = g.team_id
    if not team_id:
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    with teams_lock:
        team = teams.get(team_id)
        if not team:
            return jsonify({
                "error": "Unauthorized",
                "message": "Team not found"
            }), 401

        todo_count = len(team.todos)

