            }), 401

        # Check if at capacity
        if len(team.todos) >= team.capacity:
            return jsonify({
                "error": "Team capacity exceeded",
                "capacity": team.capacity,
                "current": len(team.todos)
            }), 403

        # Create todo with new ID
        todo_id = team.next_todo_id
        team.next_todo_id += 1

        todo = {
