            "title": title,
            "team_id": team.id,
            "completed": completed,
            "version": 1,
            "created_at": get_current_timestamp(),
            "updated_at": get_current_timestamp(),
            "tags": tags,
            "metadata": metadata
        }

        team.todos[todo_id] = todo
        if completed:
            team.completed_count += 1

